        Obtain $ y_j^{(k+1)} $ via $\eps'/\nrm{g_j^{(k)}}$-precise         tomography (\Cref{cor:EffPrepTomo}) on $\ket{\psi}$ setting $ \delta\leftarrow \delta'/(5mK) $ \tcp*[h]{query complexity is $\bigOt{ d / \eps}$}\;
        Set $ g_j^{(k+1)} \leftarrow 2\nrm{g_j^{(k)}}y_j^{(k+1)}$;  \lIf{$\nrm{g_j^{(k+1)}} > 2$}{\kwABORT}
      }
    }
    \textbf{3.)} Output the left-singular vectors of $V\!=[g_1^{(K)}\!, \ldots, g_{m}^{(K)}]$ with singular value above $\frac{1}{14}$.\kern-1mm\;
